const $ = (s) => document.querySelector(s);
const dateKey = (d = new Date()) => new Intl.DateTimeFormat('en-CA', {timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(d);
const today = dateKey();
const defaults = {name:'Suriya',tasks:[{id:1,title:'Bring the Aura concept to life',category:'Work',done:false},{id:2,title:'Read a chapter, just for yourself',category:'Personal',done:false},{id:3,title:'Step outside for a 20-minute walk',category:'Personal',done:false},{id:4,title:'Write down one thing you’re grateful for',category:'Personal',done:true}],goals:[{id:1,title:'Build a consistent reading habit',current:7,target:12,unit:'chapters',symbol:'▤'},{id:2,title:'Make movement a daily ritual',current:12,target:20,unit:'sessions',symbol:'♡'},{id:3,title:'Save for a little adventure',current:12000,target:20000,unit:'₹',symbol:'⌁'}],events:[{id:1,title:'Deep work · bring your ideas to life',time:'09:00',duration:60,date:today},{id:2,title:'A little fresh air',time:'13:00',duration:20,date:today},{id:3,title:'Wind down & reflect',time:'18:30',duration:15,date:today}],moods:[],journal:[],expenses:[{id:1,title:'Coffee & a quiet moment',amount:180,date:today},{id:2,title:'Groceries for the week',amount:1420,date:today}],budget:15000,focusMinutes:0};
let state;
try { state = {...defaults,...JSON.parse(localStorage.getItem('aura-life-v1') || 'null')}; } catch {state=structuredClone(defaults);}
let view='overview',filter='all',selectedDate=today,timer=null,seconds=25*60,focusRunning=false,toastTimeout;
const esc = (v) => String(v).replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = (n) => '₹'+Number(n).toLocaleString('en-IN');
const uid = () => Date.now()+Math.random();
function persist(){try{localStorage.setItem('aura-life-v1',JSON.stringify(state));}catch{toast('Storage is full. Your latest change is only saved for this session.');}render();}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('visible'),3200);}
const icons={overview:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',tasks:'<rect x="4" y="3" width="16" height="18" rx="3"/><path d="m8 9 2 2 4-4M8 16h8"/>',goals:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 2v6M17 2v6M3 11h18M8 15h2M14 15h2"/>',journal:'<path d="M4 3h13a3 3 0 0 1 3 3v15H7a3 3 0 0 1-3-3V3Zm0 14h16M8 7h8M8 11h5"/>',budget:'<rect x="3" y="5" width="18" height="15" rx="3"/><path d="M3 8h18M15 12h6v5h-6z"/>',aura:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5z"/>'};
const views={overview:['Overview','A little clarity for your day.','Make room for what matters. Aura will help with the rest.'],tasks:['My tasks','One thing at a time.','Clear your mind. Give your next step a little space.'],goals:['My goals','Make progress feel personal.','A little intention today. A little closer tomorrow.'],calendar:['Calendar','Find your own rhythm.','A thoughtful balance of doing, resting, and being.'],journal:['Mood & journal','Come back to yourself.','A space for your feelings, thoughts, and little discoveries.'],budget:['My budget','Spend with a little intention.','More clarity around your money. More space to breathe.'],aura:['Aura insights','A little guidance, just for you.','Personal suggestions based on your tasks, mood, and goals.']};
$('#nav').innerHTML=Object.entries(views).map(([key,val])=>`<button data-view="${key}"><svg viewBox="0 0 24 24" aria-hidden="true">${icons[key]}</svg>${val[0]}${key==='aura'?'<span class="nav-dot"></span>':''}</button>`).join('');
$('#date-label').textContent=new Intl.DateTimeFormat('en-IN',{timeZone:'Asia/Kolkata',weekday:'long',month:'long',day:'numeric',year:'numeric'}).format(new Date()).toUpperCase();
function tasksHTML(){const tasks=state.tasks.filter(t=>filter==='all'||(filter==='done'?t.done:!t.done));return tasks.length?tasks.map(t=>`<div class="task ${t.done?'done':''}"><input class="task-check" type="checkbox" ${t.done?'checked':''} aria-label="Complete ${esc(t.title)}" data-task="${t.id}"><div class="task-text"><strong>${esc(t.title)}</strong><small>${t.done?'A little win. Well done.':'Make a little progress today'}</small></div><span class="tag ${t.category==='Personal'?'personal':''}">${esc(t.category)}</span><button class="task-delete" data-delete-task="${t.id}" aria-label="Delete ${esc(t.title)}">×</button></div>`).join(''):'<p class="empty">A little breathing room. No tasks here.</p>';}
function goalsHTML(){return state.goals.length?state.goals.map(g=>{const percent=Math.min(100,Math.round(g.current/g.target*100));return `<div class="goal"><div class="goal-top"><span><span class="goal-symbol">${g.symbol||'◎'}</span>${esc(g.title)}</span><button data-progress="${g.id}" aria-label="Update progress for ${esc(g.title)}">＋ Update</button></div><div class="goal-meta"><span>${g.unit==='₹'?money(g.current)+' / '+money(g.target):g.current+' of '+g.target+' '+esc(g.unit)}</span><span>${percent}%</span></div><div class="progress" role="progressbar" aria-label="${esc(g.title)}" aria-valuenow="${percent}" aria-valuemin="0" aria-valuemax="100"><span style="width:${percent}%"></span></div></div>`;}).join(''):'<p class="empty">What would you like to grow toward?</p>';}
function eventsHTML(){const events=state.events.filter(e=>e.date===selectedDate).sort((a,b)=>a.time.localeCompare(b.time));return events.length?events.map(e=>`<div class="event"><span class="event-time">${new Date('2000-01-01T'+e.time).toLocaleTimeString('en-IN',{hour:'numeric',minute:'2-digit'})}</span><div class="event-info"><strong>${esc(e.title)}</strong><small>${e.duration} minutes · ${e.time<'12:00'?'A fresh start':e.time<'17:00'?'A little space in your afternoon':'An intentional evening'}</small></div><button class="task-delete" style="margin-left:auto" data-delete-event="${e.id}" aria-label="Delete event">×</button></div>`).join(''):'<p class="empty">Your day is open. Make room for something good.</p>';}
function weekHTML(){const now=new Date(today+'T12:00:00+05:30');const weekday=now.getDay();now.setDate(now.getDate()-((weekday+6)%7));return Array.from({length:7},(_,i)=>{const d=new Date(now);d.setDate(d.getDate()+i);const key=dateKey(d);return `<button class="day ${key===selectedDate?'selected':''}" data-day="${key}" aria-pressed="${key===selectedDate}">${d.toLocaleDateString('en-IN',{weekday:'short'})}<strong>${d.getDate()}</strong></button>`;}).join('');}
const moodNames=['Low','Okay','Balanced','Good','Great'],moodFaces=['☹','﹏','−','⌣','◡'];
function moodHTML(){const m=state.moods.find(m=>m.date===today);return moodNames.map((n,i)=>`<button class="mood-option ${m?.value===i?'selected':''}" data-mood="${i}" aria-pressed="${m?.value===i}"><span class="mood-face">${moodFaces[i]}</span>${n}</button>`).join('');}
function insight(){const mood=state.moods.find(m=>m.date===today);const pending=state.tasks.filter(t=>!t.done);if(mood && mood.value<2)return 'Today can be a gentle day. Choose one small task, then make room for a break.';if(!pending.length)return 'Your tasks are complete. Let yourself enjoy a little unplanned time — you’ve earned it.';return `You have ${pending.length} things on your mind. Start with “${pending[0].title}” and give it 25 quiet minutes.`;}
function render(){const done=state.tasks.filter(t=>t.done).length;const mood=state.moods.find(m=>m.date===today);const spent=state.expenses.filter(e=>e.date.slice(0,7)===today.slice(0,7)).reduce((sum,e)=>sum+e.amount,0);$('#profile-name').textContent=state.name;$('.profile .avatar').textContent=state.name.slice(0,1).toUpperCase();$('#profile-top').textContent=state.name.slice(0,1).toUpperCase();$('#greeting').innerHTML=`Welcome back, ${esc(state.name)}<span>.</span>`;$('#hero-message').innerHTML=mood && mood.value<2?'Give yourself a little grace today.<br>Small steps are still steps forward.':"You don't have to do it all.<br>Just the things that move you forward.";
 $('#stats').innerHTML=[['✓','Daily progress',`${done}<small>/ ${state.tasks.length} tasks</small>`,done?'Every step counts':'Your fresh start is here'],['◎','Goals in motion',`${state.goals.filter(g=>g.current<g.target).length}<small>active goals</small>`,'Growing at your own pace'],['☼','Today’s mood',`${mood?moodNames[mood.value]:'Check in'}`,mood?'A moment of self-awareness':'Make a little space for you'],['▱','Monthly spending',`${money(spent)}`,`${money(Math.abs(state.budget-spent))} ${spent>state.budget?'over budget':'left in your budget'}`]].map(([icon,label,value,trend])=>`<div class="stat"><span class="stat-icon">${icon}</span><div><span class="stat-label">${label}</span><div class="stat-value">${value}</div><div class="stat-trend">${trend}</div></div></div>`).join('');
 $('#task-count').textContent=state.tasks.filter(t=>!t.done).length;$('#task-list').innerHTML=tasksHTML();$('#goals-list').innerHTML=goalsHTML();$('#week-strip').innerHTML=weekHTML();$('#schedule-list').innerHTML=eventsHTML();$('#mood-options').innerHTML=moodHTML();$('#mood-message').textContent=mood?['Be gentle with yourself. A small step is enough.','You can take today at your own pace.','A little balance is a beautiful thing.','Keep a little of this feeling for yourself.','Let this good energy carry you gently.'][mood.value]:'Your feelings deserve a little space.';$('#insight-text').textContent=insight();
 document.querySelectorAll('nav [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));document.querySelectorAll('.task-tabs [data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===filter));$('#page-title').textContent=views[view][1];$('#page-subtitle').textContent=views[view][2];$('#breadcrumb').innerHTML=`${esc(views[view][0])} <span>/</span> <strong>${view==='overview'?'Today':'Your space'}</strong>`;$('#overview').hidden=view!=='overview';$('#detail-view').hidden=view==='overview';if(view!=='overview')renderDetail(spent);
}
function panel(title,body,action='',wide=false){return `<section class="panel ${wide?'wide':''}"><div class="panel-heading"><h2>${title}</h2>${action}</div>${body}</section>`;}
const addButton=(action,label)=>`<button class="text-btn" data-action="${action}">＋ ${label}</button>`;
function renderDetail(spent){let html='';if(view==='tasks')html=panel('Your tasks',`<div class="task-tabs">${['all','active','done'].map(f=>`<button class="${filter===f?'active':''}" data-filter="${f}">${f==='all'?'All tasks':f==='active'?'To do':'Completed'}</button>`).join('')}</div>${tasksHTML()}`,addButton('task','Add task'),true);if(view==='goals')html=panel('What you’re growing toward',goalsHTML(),addButton('goal','New goal'),true);if(view==='calendar')html=panel('Your schedule',`<label>Choose a day<input type="date" id="calendar-date" value="${selectedDate}"></label>${weekHTML()?'<div class="week-strip">'+weekHTML()+'</div>':''}${eventsHTML()}`,addButton('event','Add event'),true);if(view==='journal')html=panel('How are you feeling?',`<div class="mood-options">${moodHTML()}</div><p class="modal-note">Your check-in can help Aura suggest a gentler or more focused day.</p>`,addButton('journal','Write a note'))+panel('Your reflections',state.journal.length?state.journal.slice().reverse().map(j=>`<div class="journal-entry"><small>${esc(j.date)} · ${j.mood===null?'A moment of reflection':moodNames[j.mood]}</small><p>${esc(j.text)}</p></div>`).join(''):'<p class="empty">A thought, a tiny win, or something to let go of.</p>');if(view==='budget')html=panel('Your monthly picture',`<div class="budget-value">${money(spent)} <small>of ${money(state.budget)}</small></div><div class="progress"><span style="width:${Math.min(100,spent/state.budget*100)}%"></span></div><p class="modal-note" style="margin-top:20px">${spent>state.budget?money(spent-state.budget)+' over your monthly budget.':money(state.budget-spent)+' available for the rest of the month.'}</p><button class="text-btn" style="margin-top:15px" data-action="budget">Adjust monthly budget ↗</button>`)+panel('Spending journal',state.expenses.slice().reverse().map(e=>`<div class="expense"><span>${esc(e.title)}<br><small>${esc(e.date)}</small></span><span>${money(e.amount)} <button class="icon-btn" data-delete-expense="${e.id}" aria-label="Delete expense">×</button></span></div>`).join('')||'<p class="empty">No expenses yet.</p>',addButton('expense','Add expense'));if(view==='aura')html=panel('Your daily guidance',`<p class="modal-note">Aura’s first version uses simple rules based on your activity. These suggestions are generated on your device.</p><div class="suggestion"><h3>Give your next step a little space</h3><p>${esc(insight())}</p><button class="text-btn" data-action="focus">Start a focus session ↗</button></div><div class="suggestion"><h3>Notice the little things</h3><p>${state.moods.some(m=>m.date===today)?'You made space to check in today. Capture a thought about what shaped your mood.':'Before making a plan, take a moment to check in with yourself.'}</p><button class="text-btn" data-view="journal">Check in with yourself ↗</button></div>`)+panel('A little time to focus',`<div class="focus-display"><span class="eyebrow">ONE THING. A LITTLE ATTENTION.</span><strong id="timer-time">${timerText()}</strong><p>${focusRunning?'Your quiet moment is underway.':'A gentle 25-minute focus session.'}</p><div class="focus-controls"><button class="button primary" data-action="timer">${focusRunning?'Pause':'Start focus'}</button><button class="button secondary" data-action="reset-timer">Reset</button></div><p>${state.focusMinutes} minutes of focus completed</p></div>`);$('#detail-view').innerHTML=`<div class="detail-grid">${html}</div>`;}
function navigate(next){if(!views[next])return;view=next;$('#sidebar')?.classList.remove('open');$('.sidebar').classList.remove('open');render();window.scrollTo({top:0,behavior:'smooth'});}
function field(label,name,type='text',value='',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra} required></label>`;}
function modal(title,fields,onSave,submit='Save'){const dialog=$('#modal');$('#modal-title').textContent=title;$('#modal-fields').innerHTML=fields;$('#modal-submit').textContent=submit;$('#modal-form').onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.currentTarget));onSave(values);dialog.close();};dialog.showModal();}
function taskModal(){modal('Make room for a task',field('What’s your next step?','title','text','','maxlength="160"')+'<label>A little context<select name="category"><option>Work</option><option>Personal</option></select></label>',v=>{state.tasks.push({id:uid(),title:v.title.trim(),category:v.category,done:false});persist();toast('A little clarity added to your day.');});}
function eventModal(){modal('Make a little time',field('What would you like to do?','title','text','','maxlength="160"')+field('Day','date','date',selectedDate)+field('Start time','time','time','10:00')+field('Duration in minutes','duration','number','30','min="5" max="1440"'),v=>{state.events.push({id:uid(),...v,duration:Number(v.duration)});selectedDate=v.date;persist();toast('A little time, set aside.');});}
function goalModal(){modal('A dream to grow toward',field('Your goal','title','text','','maxlength="160"')+field('Target','target','number','10','min="1" max="100000000"')+field('What are you counting?','unit','text','sessions','maxlength="20"'),v=>{state.goals.push({id:uid(),title:v.title.trim(),current:0,target:Number(v.target),unit:v.unit,symbol:'◎'});persist();toast('Your next chapter starts here.');});}
function journalModal(){modal('A moment for yourself','<label>What’s on your mind?<textarea name="text" placeholder="Today, I noticed…" maxlength="5000" required></textarea></label><p class="modal-note">Your reflections stay in this browser, on this device.</p>',v=>{state.journal.push({id:uid(),date:today,text:v.text.trim(),mood:state.moods.find(m=>m.date===today)?.value??null});persist();toast('Your thought has a little space now.');});}
function profileModal(){modal('Make this space yours',field('What should Aura call you?','name','text',state.name,'maxlength="30"'),v=>{state.name=v.name.trim()||'Friend';persist();toast('Welcome to your space, '+state.name+'.');});}
function expenseModal(){modal('A little spending clarity',field('What did you spend on?','title','text','','maxlength="160"')+field('Amount in ₹','amount','number','','min="0.01" max="100000000" step="0.01"')+field('Date','date','date',today),v=>{state.expenses.push({id:uid(),title:v.title.trim(),amount:Number(v.amount),date:v.date});persist();toast('Expense recorded.');});}
function timerText(){return `${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;}
function toggleTimer(){if(focusRunning){clearInterval(timer);focusRunning=false;render();return;}focusRunning=true;timer=setInterval(()=>{seconds--;if($('#timer-time'))$('#timer-time').textContent=timerText();if(seconds<=0){clearInterval(timer);focusRunning=false;state.focusMinutes+=25;seconds=1500;persist();toast('25 minutes of intention. Take a little break.');}},1000);render();}
const actions={task:taskModal,event:eventModal,goal:goalModal,journal:journalModal,expense:expenseModal,budget:()=>modal('Your monthly intention',field('Monthly budget in ₹','budget','number',state.budget,'min="1" max="100000000"'),v=>{state.budget=Number(v.budget);persist();toast('Budget updated.');}),focus:()=>navigate('aura'),timer:toggleTimer,'reset-timer':()=>{clearInterval(timer);focusRunning=false;seconds=1500;render();}};
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.view)navigate(b.dataset.view);if(b.dataset.action)actions[b.dataset.action]?.();if(b.dataset.filter){filter=b.dataset.filter;render();}if(b.dataset.mood!==undefined){const value=Number(b.dataset.mood);state.moods=state.moods.filter(m=>m.date!==today);state.moods.push({date:today,value});persist();toast('A moment of awareness, saved.');}if(b.dataset.day){selectedDate=b.dataset.day;render();}if(b.dataset.deleteTask){state.tasks=state.tasks.filter(t=>t.id!==Number(b.dataset.deleteTask));persist();}if(b.dataset.deleteEvent){state.events=state.events.filter(t=>t.id!==Number(b.dataset.deleteEvent));persist();}if(b.dataset.deleteExpense){state.expenses=state.expenses.filter(t=>t.id!==Number(b.dataset.deleteExpense));persist();}if(b.dataset.progress){const g=state.goals.find(g=>g.id===Number(b.dataset.progress));modal('Every little step counts',`<p class="modal-note">${esc(g.title)}</p>`+field('Current progress ('+esc(g.unit)+')','current','number',g.current,`min="0" max="${g.target}"`),v=>{g.current=Number(v.current);persist();toast(g.current===g.target?'A goal reached. Take a moment to celebrate.':'Progress is progress. Keep going.');});}});
document.addEventListener('change',e=>{if(e.target.dataset.task){const t=state.tasks.find(t=>t.id===Number(e.target.dataset.task));t.done=e.target.checked;persist();if(t.done)toast('One little win. Well done.');}if(e.target.id==='calendar-date'){selectedDate=e.target.value;render();}});
$('#quick-add').onclick=()=>modal('What’s on your mind?','<label>Make a little space for<select name="type"><option value="task">A task</option><option value="event">A calendar event</option><option value="goal">A goal</option><option value="journal">A journal note</option><option value="expense">An expense</option></select></label>',v=>setTimeout(()=>actions[v.type](),0),'Continue');
$('#add-task').onclick=taskModal;$('#add-event').onclick=eventModal;$('#add-goal').onclick=goalModal;$('#journal').onclick=journalModal;$('#profile').onclick=profileModal;$('#profile-top').onclick=profileModal;$('#reflection').onclick=journalModal;$('#notifications').onclick=()=>navigate('aura');$('#focus-start').onclick=()=>navigate('aura');$('#plan-day').onclick=()=>{navigate('tasks');toast('Choose one priority. Let the rest follow.');};$('#menu').onclick=()=>$('.sidebar').classList.toggle('open');$('#modal-close').onclick=$('#modal-cancel').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
render();
